create table public.habits(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),title text not null,emoji text not null default '🔥',color text not null default '#F28C45',frequency_type text not null default 'daily',target_count integer not null default 1,habit_type text not null default 'boolean',goal_id uuid references public.goals(id) on delete set null,is_archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.habit_entries(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),habit_id uuid not null references public.habits(id) on delete cascade,entry_date date not null default current_date,value numeric,is_completed boolean not null default true,notes text,created_at timestamptz not null default now(),unique(habit_id,entry_date));
create table public.health_entries(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),entry_type text not null,value_numeric numeric,value_text text,unit text,entry_date date not null default current_date,notes text,created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.workouts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),title text not null,workout_type text not null,emoji text not null default '🏋️',date date not null default current_date,duration_minutes integer,intensity text,is_completed boolean not null default true,habit_id uuid references public.habits(id) on delete set null,goal_id uuid references public.goals(id) on delete set null,created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.family_profiles(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,relationship text not null,emoji text not null default '❤️',birth_date date,created_at timestamptz not null default now());create table public.family_entries(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),title text not null,entry_type text not null,emoji text not null default '❤️',date date not null default current_date,quality smallint check(quality between 1 and 5),created_at timestamptz not null default now(),deleted_at timestamptz);create table public.v20_meetings(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),meeting_date date not null,status text not null default 'planned',notes text,created_at timestamptz not null default now());create table public.experiences(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),title text not null,emoji text not null default '🌎',status text not null default 'planned',target_date date,estimated_cost numeric,actual_cost numeric,goal_id uuid references public.goals(id) on delete set null,created_at timestamptz not null default now(),deleted_at timestamptz);
alter table public.habits enable row level security;alter table public.habit_entries enable row level security;alter table public.health_entries enable row level security;alter table public.workouts enable row level security;alter table public.family_profiles enable row level security;alter table public.family_entries enable row level security;alter table public.v20_meetings enable row level security;alter table public.experiences enable row level security;grant select,insert,update,delete on public.habits,public.habit_entries,public.health_entries,public.workouts,public.family_profiles,public.family_entries,public.v20_meetings,public.experiences to authenticated;
